def multiply_all(*args):
    result = 1
    for a in args:
        result *= a
    return result

print(multiply_all(2, 3, 4))

def make_tag(tag, **kwargs):
    attrs = ' '.join(f'{k}={v}' for k, v in kwargs.items())
    if attrs:
        return f'<{tag} {attrs}>'
    return f'<{tag}>'


print(make_tag('a', href='google.com'))
